const express = require('express');
const fs = require('fs').promises;
const path = require('path');
const db = require('../db');

const app = express();
app.use(express.json());

const SNAPSHOT_DIR = path.resolve(__dirname, '../wasm_snapshots');

app.post('/api/wasm/state/:snapshotId/resume', async (req, res) => {
  const { snapshotId } = req.params;

  // Validate that the simulation snapshot belongs to the authenticated user
  const record = await db('wasm_simulation_snapshots')
    .where({ id: snapshotId, user_id: req.user.id })
    .first();
  if (!record) {
    return res.status(404).json({ error: 'Simulation snapshot not found' });
  }

  const snapshotFile = path.join(SNAPSHOT_DIR, `${snapshotId}.bin`);

  try {
    const memorySnapshot = await fs.readFile(snapshotFile);

    const memory = new WebAssembly.Memory({ initial: 256, maximum: 512 });
    const memoryView = new Uint8Array(memory.buffer);
    memoryView.set(memorySnapshot);

    const wasmCode = await fs.readFile(path.resolve(__dirname, '../bin/simulation.wasm'));
    const module = await WebAssembly.instantiate(wasmCode, { env: { memory } });

    const stateCheckpoint = module.instance.exports.compute_checkpoint();
    return res.json({ snapshotId, checkpoint: stateCheckpoint });
  } catch (err) {
    return res.status(500).json({ error: 'Could not resume WASM simulation state' });
  }
});

module.exports = app;
